// Exact comparison P^T S B = T, without expanding a weight-eight word tensor.
// P and B are the certified prefix/suffix maps; T is an independent literature
// boundary. This executable only compares a supplied candidate, never solves it.
#include "symrep_io.hpp"
using namespace symrep;
static double seconds(std::chrono::steady_clock::time_point s){return std::chrono::duration<double>(std::chrono::steady_clock::now()-s).count();}
struct Heights {int_t den=1,maxnum=0,maxrowsum=0,maxcolsum=0;};
static Heights heights(const Mat&m,bool columns=false){Heights h;std::vector<int_t>sumcol(columns?m.ncol:0);for(auto&row:m.rows){int_t s=0;for(auto[j,x]:row){auto a=x.num().abs();s+=a;if(a>h.maxnum)h.maxnum=a;if(!x.is_integer())h.den=LCM(h.den,x.den());if(columns)sumcol[j]+=a;}if(s>h.maxrowsum)h.maxrowsum=s;}for(auto&s:sumcol)if(s>h.maxcolsum)h.maxcolsum=s;return h;}
struct Result {bool equal=true;size_t attempted=0;std::vector<ulong>primes;int_t bound=0,modulus=1;I prefix=-1,suffix=-1;Q actual=0,expected=0;};
static Q exact_entry(const Mat&P,const Mat&S,const Mat&B,I i,I j){Q answer=0;std::vector<Q>column(B.nrow);for(size_t t=0;t<B.nrow;++t)if(auto x=B[t].find(j))column[t]=*x;for(size_t f=0;f<P.nrow;++f)if(auto p=P[f].find(i)){Q local=0;for(auto[t,x]:S[f])if(column[t]!=0)local+=x*column[t];answer+=(*p)*local;}return answer;}
static Result compare(const Mat&P,const Mat&S,const Mat&B,const Mat&T,bool progress){
 require(P.nrow==S.nrow&&S.ncol==B.nrow&&T.nrow==P.ncol&&T.ncol==B.ncol,"boundary comparison shapes");auto start=std::chrono::steady_clock::now();auto hp=heights(P,true),hs=heights(S),hb=heights(B),ht=heights(T);int_t scale=hp.den*hs.den*hb.den*ht.den;Result answer;answer.bound=scale*(ht.maxnum+hp.maxcolsum*hs.maxrowsum*hb.maxnum);
 // scale*(P^T S B-T) is integral, and every entry has absolute value <= bound.
 // Complete zero residues for coprime good moduli with product > bound force
 // exact equality. n_nextprime(...,1) requests proven word-size primality.
 if(progress)std::cout<<"COMPARISON_HEIGHT bits="<<answer.bound.bits()<<" prefix_rows="<<P.ncol<<" raw_suffix="<<B.ncol<<" seconds="<<seconds(start)<<std::endl;
 ulong prime=n_nextprime(1ULL<<60,1);
 while(answer.modulus<=answer.bound){if(scale%prime==0){prime=n_nextprime(prime,1);continue;}++answer.attempted;field_t fp(FIELD_Fp,prime);using MM=sparse_mat<ulong,I>;MM sm(S.nrow,S.ncol),bm(B.nrow,B.ncol);for(size_t i=0;i<S.nrow;++i)sm[i]=S[i]%fp.mod;for(size_t i=0;i<B.nrow;++i)bm[i]=B[i]%fp.mod;std::vector<ulong>prefix(P.ncol*S.ncol);
  for(size_t f=0;f<P.nrow;++f){if(!sm[f].nnz())continue;for(auto[i,xq]:P[f]){ulong x=xq%fp.mod,pre=n_mulmod_precomp_shoup(x,prime);auto*row=&prefix[size_t(i)*S.ncol];for(auto[t,y]:sm[f])row[t]=_nmod_add(row[t],n_mulmod_shoup(x,y,pre,prime),fp.mod);}if(progress&&(f+1)%8192==0)std::cout<<"PREFIX_CONTRACT prime="<<prime<<" rows="<<f+1<<" seconds="<<seconds(start)<<std::endl;}
  std::vector<ulong>actual(B.ncol),expected(B.ncol);
  for(size_t i=0;i<P.ncol;++i){std::fill(actual.begin(),actual.end(),0);std::fill(expected.begin(),expected.end(),0);for(size_t t=0;t<S.ncol;++t)if(auto x=prefix[i*S.ncol+t]){ulong pre=n_mulmod_precomp_shoup(x,prime);for(auto[j,y]:bm[t])actual[j]=_nmod_add(actual[j],n_mulmod_shoup(x,y,pre,prime),fp.mod);}for(auto[j,x]:T[i])expected[j]=x%fp.mod;
   for(size_t j=0;j<B.ncol;++j)if(actual[j]!=expected[j]){answer.equal=false;answer.prefix=index(i);answer.suffix=index(j);answer.actual=exact_entry(P,S,B,index(i),index(j));if(auto x=T[i].find(index(j)))answer.expected=*x;require(answer.actual!=answer.expected,"modular mismatch failed independent exact witness replay");if(progress)std::cout<<"EXACT_MISMATCH prefix="<<i<<" suffix="<<j<<" actual="<<answer.actual<<" expected="<<answer.expected<<" seconds="<<seconds(start)<<std::endl;return answer;}
  }
  answer.primes.push_back(prime);answer.modulus*=prime;if(progress)std::cout<<"CERT_PRIME prime="<<prime<<" all_components="<<P.ncol*B.ncol<<" modulus_bits="<<answer.modulus.bits()<<" bound_bits="<<answer.bound.bits()<<" seconds="<<seconds(start)<<std::endl;prime=n_nextprime(prime,1);
 }
 require(answer.modulus>answer.bound,"exact comparison certificate modulus");return answer;
}
static void set(Mat&a,size_t i,I j,const Q&v){a[i].push_back(j,v);normalize(a[i]);}
static Mat candidate_matrix(const Tensor&t,size_t tails){if(t.rank()==2&&t.dim(1)==tails)return flatten(t);require(t.rank()==3&&t.dim(0)==1&&t.dim(2)==tails,"candidate is [prefix,tail] or [1,prefix,tail]");Mat s(t.dim(1),tails);for(size_t k=0;k<t.nnz();++k){auto ix=t.index(k);s[ix[0]].push_back(index(ix[1]),t.val(k));}for(auto&row:s.rows)normalize(row);return s;}
static int self_test(){auto start=std::chrono::steady_clock::now();Mat p(3,2),s(3,3),b(3,4);set(p,0,0,Q(2)/Q(3));set(p,0,1,Q(-1)/Q(5));set(p,1,0,Q(7)/Q(11));set(p,2,1,Q(3)/Q(2));set(s,0,0,Q(1)/Q(2));set(s,0,2,Q(-3)/Q(7));set(s,1,1,Q(5)/Q(13));set(s,2,0,Q(-2)/Q(3));set(s,2,2,Q(9)/Q(2));set(b,0,0,Q(2)/Q(5));set(b,0,3,Q(-1)/Q(3));set(b,1,1,Q(4)/Q(7));set(b,2,0,Q(-3)/Q(11));set(b,2,2,Q(8)/Q(9));
 Mat sf(1,9);for(size_t i=0;i<3;++i)for(auto[j,x]:s[i])sf[0].push_back(index(i*3+j),x);require(equal(candidate_matrix(tensor(s,{3,3}),3),s)&&equal(candidate_matrix(tensor(sf,{1,3,3}),3),s),"both supported candidate tensor coordinate conventions");
 auto t=mul(transpose(p),mul(s,b));auto good=compare(p,s,b,t,false);require(good.equal,"generic rational two-map fixture");auto wrong_s=s;set(wrong_s,0,0,Q(1)/Q(17));auto bad=compare(p,wrong_s,b,t,false);require(!bad.equal&&bad.actual-bad.expected==Q(4)/Q(255),"perturbed candidate exact witness");
 auto blind=t;ulong prime=n_nextprime(1ULL<<60,1);set(blind,0,0,Q(prime));auto two=compare(p,s,b,blind,false);require(!two.equal&&two.attempted>=2&&two.actual-two.expected==-Q(prime),"first-prime invisible discrepancy requires second modulus");require(bad.primes.empty()&&two.primes.size()==1&&two.primes[0]==prime,"accepted-prime receipt tracking excludes the failing pass");Mat z(3,3);auto zerot=mul(transpose(p),mul(z,b));require(compare(p,z,b,zerot,false).equal,"zero source exact comparison");
 std::cout<<"{\"all_checks_pass\":true,\"nonunit_denominators_and_both_maps\":true,\"matrix_and_rank_three_candidate_formats\":true,\"perturbed_candidate_exact_difference\":\""<<bad.actual-bad.expected<<"\",\"first_prime_invisible_error_rejected\":true,\"accepted_prime_tracking\":true,\"zero_case_pass\":true,\"independent_expected_value_method\":\"complete rational matrix products\",\"physical_inputs_read\":false,\"seconds\":"<<seconds(start)<<"}\n";return 0;}
int main(int argc,char**argv){try{
 if(argc==2&&std::string(argv[1])=="--self-test")return self_test();
 require(argc==5,"usage boundary_holdout_compare EXPERIMENT DC|TC CANDIDATE OUTPUT_LABEL");fs::path exp=argv[1];std::string name=argv[2],label=argv[4];require((name=="DC"||name=="TC")&&label.find('/')==std::string::npos&&label!="."&&label!="..","boundary/output label");fs::path dir=exp/"boundary"/name,out=exp/"holdouts"/label;fresh(out);auto start=std::chrono::steady_clock::now();auto t=read(argv[3]);Mat s;
 s=candidate_matrix(t,175);t.clear();
 auto p=read_matrix(dir/"collinear/first_w6.wxf"),b=read_matrix(dir/"suffix_TF175_raw2.wxf");auto target=read(exp/"holdouts"/(name+"_prefix_probe")/"F4_target_prefix6_raw2.wxf");require(target.rank()==3&&target.dim(1)==target.dim(2),"target raw pair shape");size_t q=target.dim(1);auto expected=flatten(target);target.clear();std::cout<<"INPUT candidate_nnz="<<s.nnz()<<" prefix_map_nnz="<<p.nnz()<<" target_nnz="<<expected.nnz()<<" seconds="<<seconds(start)<<std::endl;
 auto result=compare(p,s,b,expected,true);if(!result.equal){Mat witness(p.ncol,q*q);witness[result.prefix].push_back(result.suffix,result.actual-result.expected);write_tensor_view(out/"exact_difference_witness.wxf",MatrixTensorView(witness,{p.ncol,q,q}));}
 std::ofstream receipt(out/"receipt.json");receipt<<"{\"boundary\":\""<<name<<"\",\"exact_boundary_equality\":"<<(result.equal?"true":"false")<<",\"candidate_prefix_dimension\":"<<s.nrow<<",\"boundary_prefix_dimension\":"<<p.ncol<<",\"boundary_alphabet\":"<<q<<",\"output_component_count\":"<<p.ncol*q*q<<",\"all_output_components_certified\":"<<(result.equal?"true":"false")<<",\"certificate_primes\":"<<result.primes.size()<<",\"accepted_primes\":[";for(size_t i=0;i<result.primes.size();++i){if(i)receipt<<',';receipt<<result.primes[i];}receipt<<"],\"attempted_primes\":"<<result.attempted<<",\"certificate_modulus\":\""<<result.modulus<<"\",\"certificate_integer_bound\":\""<<result.bound<<"\",\"exact_difference_witness\":["<<result.prefix<<','<<result.suffix<<"],\"actual_witness_value\":\""<<result.actual<<"\",\"expected_witness_value\":\""<<result.expected<<"\",\"zero_based_witness_indices\":true,\"weight_eight_word_expansion\":false,\"candidate_modified\":false,\"target_independent_but_projection_maps_shared\":true,\"scope\":\"Exact comparison of the supplied candidate boundary only; no global existence or uniqueness conclusion.\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"COMPARE_COMPLETE equal="<<result.equal<<" seconds="<<seconds(start)<<std::endl;return result.equal?0:2;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
